-- GENERATED by scripts/build_sql.py from mock_data. Do not edit.
-- Policy: reset_mode=EVENTS_ONLY, schedule=0 1 * * *, enabled=true
--
-- EVENTS_ONLY: clears orders, fulfillments, deliveries and inventory, keeps master data.
-- FULL:        also clears customers, sites, products, carriers and distribution centers.
-- Master data and events are then reloaded from mock_data.

CREATE OR REPLACE FUNCTION operations.refresh_demo_environment(p_reset_mode text DEFAULT 'EVENTS_ONLY')
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, core, commercial, operations
AS $$
BEGIN
    IF p_reset_mode NOT IN ('EVENTS_ONLY', 'FULL') THEN
        RAISE EXCEPTION 'p_reset_mode must be EVENTS_ONLY or FULL';
    END IF;

    DELETE FROM operations.deliveries;
    DELETE FROM operations.fulfillment_lines;
    DELETE FROM operations.fulfillments;
    DELETE FROM commercial.sales_order_lines;
    DELETE FROM commercial.sales_orders;
    DELETE FROM operations.inventory_balances;

    IF p_reset_mode = 'FULL' THEN
        DELETE FROM core.delivery_sites;
        DELETE FROM core.customers;
        DELETE FROM core.products;
        DELETE FROM core.carriers;
        DELETE FROM core.distribution_centers;
    END IF;

    -- GENERATED by scripts/build_sql.py from mock_data/master. Do not edit.

    INSERT INTO core.distribution_centers (code, name, city, country_code)
    SELECT v.code, v.name, v.city, v.country_code
    FROM (VALUES
        ('DC-STO', 'Stockholm North DC', 'Stockholm', 'SE'),
        ('DC-GOT', 'Gothenburg DC', 'Gothenburg', 'SE'),
        ('DC-MAL', 'Malmo DC', 'Malmo', 'SE')
    ) AS v(code, name, city, country_code)
    ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, city = EXCLUDED.city, country_code = EXCLUDED.country_code;

    INSERT INTO core.carriers (code, name)
    SELECT v.code, v.name
    FROM (VALUES
        ('NORDIC-LOG', 'Nordic Logistics AB'),
        ('BYGG-EXPRESS', 'Bygg Express AB'),
        ('SKANDI-FREIGHT', 'Skandi Freight AB')
    ) AS v(code, name)
    ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name;

    INSERT INTO core.products (sku, name, category, unit_of_measure, unit_weight_kg, is_bulky)
    SELECT v.sku, v.name, v.category, v.unit_of_measure, v.unit_weight_kg::numeric, v.is_bulky::boolean
    FROM (VALUES
        ('TRB-45X95-3600', 'Construction timber 45x95 mm, 3.6 m', 'TIMBER', 'EACH', '8.2', 'True'),
        ('TRB-45X145-4800', 'Construction timber 45x145 mm, 4.8 m', 'TIMBER', 'EACH', '16.4', 'True'),
        ('GYP-13-1200X2400', 'Gypsum board 13 mm, 1200x2400', 'PLASTERBOARD', 'SHEET', '28.0', 'True'),
        ('CEM-25', 'General purpose cement 25 kg', 'CEMENT', 'BAG', '25.0', 'False'),
        ('ISO-100-1200', 'Mineral wool insulation 100 mm', 'INSULATION', 'SHEET', '6.5', 'True'),
        ('TOOL-LASER', 'Cross-line laser level', 'TOOLS', 'EACH', '1.8', 'False')
    ) AS v(sku, name, category, unit_of_measure, unit_weight_kg, is_bulky)
    ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, unit_of_measure = EXCLUDED.unit_of_measure, unit_weight_kg = EXCLUDED.unit_weight_kg, is_bulky = EXCLUDED.is_bulky;

    INSERT INTO core.customers (customer_number, name, customer_type, tier, sla_hours, email, phone, preferred_language)
    SELECT v.customer_number, v.name, v.customer_type, v.tier, v.sla_hours::integer, v.email, v.phone, v.preferred_language
    FROM (VALUES
        ('C-10001', 'Nordbygg Entreprenad AB', 'B2B', 'STRATEGIC', '24', 'inkop@nordbygg.example', '+46 8 555 10001', 'sv'),
        ('C-10002', 'Vastkust Byggpartner AB', 'B2B', 'KEY', '48', 'order@vastkust.example', '+46 31 555 10002', 'sv'),
        ('C-10003', 'Malmohus Projekt AB', 'B2B', 'KEY', '48', 'projekt@malmohus.example', '+46 40 555 10003', 'sv'),
        ('C-20001', 'Anna Lindstrom', 'B2C', 'STANDARD', '72', 'anna.lindstrom@example', '+46 70 555 20001', 'sv'),
        ('C-20002', 'Erik Johansson', 'B2C', 'STANDARD', '72', 'erik.johansson@example', '+46 70 555 20002', 'en')
    ) AS v(customer_number, name, customer_type, tier, sla_hours, email, phone, preferred_language)
    ON CONFLICT (customer_number) DO UPDATE SET name = EXCLUDED.name, customer_type = EXCLUDED.customer_type, tier = EXCLUDED.tier, sla_hours = EXCLUDED.sla_hours, email = EXCLUDED.email, phone = EXCLUDED.phone, preferred_language = EXCLUDED.preferred_language;

    INSERT INTO core.delivery_sites (customer_id, site_name, address_line, postcode, city, access_notes, contact_name, contact_phone)
    SELECT c.id, v.site_name, v.address_line, v.postcode, v.city, v.access_notes, v.contact_name, v.contact_phone
    FROM (VALUES
        ('C-10001', 'North Harbor project', 'Hammarby Kaj 12', '120 30', 'Stockholm', 'Crane truck must call 30 minutes ahead.', 'Lars Berg', '+46 70 600 1001'),
        ('C-10002', 'Lindholmen site', 'Lindholmspiren 5', '417 56', 'Gothenburg', 'Delivery before 15:00 only.', 'Sara Nilsson', '+46 70 600 1002'),
        ('C-10003', 'Soder project', 'Sodra Forstadsgatan 44', '211 43', 'Malmo', 'Use entrance B.', 'Oskar Ek', '+46 70 600 1003'),
        ('C-20001', 'Private renovation', 'Birkagatan 8', '113 39', 'Stockholm', 'Small van preferred.', 'Anna Lindstrom', '+46 70 555 20001'),
        ('C-20002', 'Villa renovation', 'Sankt Sigfrids Plan 2', '412 65', 'Gothenburg', 'Call on arrival.', 'Erik Johansson', '+46 70 555 20002')
    ) AS v(customer_number, site_name, address_line, postcode, city, access_notes, contact_name, contact_phone)
    JOIN core.customers c ON c.customer_number = v.customer_number
    WHERE NOT EXISTS (
        SELECT 1 FROM core.delivery_sites ds
        WHERE ds.customer_id = c.id AND ds.address_line = v.address_line
    );

    INSERT INTO operations.inventory_balances (distribution_center_id, product_id, on_hand_quantity, reserved_quantity)
    SELECT dc.id, p.id, v.on_hand_quantity::numeric, v.reserved_quantity::numeric
    FROM (VALUES
        ('DC-STO', 'TRB-45X95-3600', '120', '0'),
        ('DC-STO', 'TRB-45X145-4800', '120', '0'),
        ('DC-STO', 'GYP-13-1200X2400', '80', '0'),
        ('DC-STO', 'CEM-25', '300', '0'),
        ('DC-STO', 'ISO-100-1200', '100', '0'),
        ('DC-STO', 'TOOL-LASER', '25', '0'),
        ('DC-GOT', 'TRB-45X95-3600', '120', '0'),
        ('DC-GOT', 'TRB-45X145-4800', '120', '0'),
        ('DC-GOT', 'GYP-13-1200X2400', '12', '0'),
        ('DC-GOT', 'CEM-25', '300', '0'),
        ('DC-GOT', 'ISO-100-1200', '100', '0'),
        ('DC-GOT', 'TOOL-LASER', '25', '0'),
        ('DC-MAL', 'TRB-45X95-3600', '18', '0'),
        ('DC-MAL', 'TRB-45X145-4800', '18', '0'),
        ('DC-MAL', 'GYP-13-1200X2400', '80', '0'),
        ('DC-MAL', 'CEM-25', '300', '0'),
        ('DC-MAL', 'ISO-100-1200', '100', '0'),
        ('DC-MAL', 'TOOL-LASER', '25', '0')
    ) AS v(dc_code, sku, on_hand_quantity, reserved_quantity)
    JOIN core.distribution_centers dc ON dc.code = v.dc_code
    JOIN core.products p ON p.sku = v.sku
    ON CONFLICT (distribution_center_id, product_id) DO UPDATE SET
        on_hand_quantity = EXCLUDED.on_hand_quantity,
        reserved_quantity = EXCLUDED.reserved_quantity,
        updated_at = now();

    -- GENERATED by scripts/build_sql.py from mock_data/events. Do not edit.

